export interface Frontmatter {
  title: string;
  date: Date | null;
  tags: string[];
  draft: boolean;
  layout?: string;
  [key: string]: unknown;
}

export interface Page {
  /** Path of source file relative to source dir, e.g. "posts/hello.md" */
  sourcePath: string;
  /** Output path relative to out dir, e.g. "posts/hello.html" */
  outputPath: string;
  /** Site-absolute URL, e.g. "/posts/hello.html" */
  url: string;
  frontmatter: Frontmatter;
  /** Raw markdown body (without frontmatter) */
  body: string;
  /** Rendered HTML of body */
  html: string;
  /** Plain-text excerpt for feeds/listings */
  excerpt: string;
}

export interface SiteConfig {
  source: string;
  templates: string;
  out: string;
  /** Base URL used for RSS absolute links */
  baseUrl: string;
  title: string;
  description: string;
  /** Include draft pages in the build */
  drafts: boolean;
}

export interface BuildResult {
  pages: Page[];
  tagPages: string[];
  wroteFiles: string[];
}

export const DEFAULT_CONFIG: SiteConfig = {
  source: 'content',
  templates: 'templates',
  out: 'dist-site',
  baseUrl: 'https://example.com',
  title: 'My Site',
  description: 'A static site',
  drafts: false,
};

import matter from 'gray-matter';
import type { Frontmatter } from './types.js';

export interface ParsedDocument {
  frontmatter: Frontmatter;
  body: string;
}

function toDate(value: unknown): Date | null {
  if (value instanceof Date && !isNaN(value.getTime())) return value;
  if (typeof value === 'string' || typeof value === 'number') {
    const d = new Date(value);
    if (!isNaN(d.getTime())) return d;
  }
  return null;
}

function toTags(value: unknown): string[] {
  if (Array.isArray(value)) {
    return value.map((t) => String(t).trim()).filter(Boolean);
  }
  if (typeof value === 'string') {
    return value
      .split(',')
      .map((t) => t.trim())
      .filter(Boolean);
  }
  return [];
}

/**
 * Parse a markdown document with optional YAML frontmatter.
 * Normalizes: title (string), date (Date|null), tags (string[]), draft (boolean).
 * Extra keys are preserved as-is.
 */
export function parseFrontmatter(raw: string, fallbackTitle = 'Untitled'): ParsedDocument {
  const { data, content } = matter(raw);
  const { title, date, tags, draft, ...rest } = data as Record<string, unknown>;

  const frontmatter: Frontmatter = {
    ...rest,
    title: typeof title === 'string' && title.trim() ? title.trim() : fallbackTitle,
    date: toDate(date),
    tags: toTags(tags),
    draft: draft === true || draft === 'true',
  };

  return { frontmatter, body: content };
}

/** Derive a short plain-text excerpt from a markdown body. */
export function makeExcerpt(markdown: string, maxLength = 200): string {
  const text = markdown
    .replace(/```[\s\S]*?```/g, ' ') // fenced code blocks
    .replace(/`[^`]*`/g, ' ') // inline code
    .replace(/!\[[^\]]*\]\([^)]*\)/g, ' ') // images
    .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1') // links -> text
    .replace(/^#{1,6}\s+/gm, '') // headings
    .replace(/[*_>~#-]/g, ' ') // md punctuation
    .replace(/\s+/g, ' ')
    .trim();
  return text.length > maxLength ? text.slice(0, maxLength - 1).trimEnd() + '\u2026' : text;
}

import MarkdownIt from 'markdown-it';
import hljs from 'highlight.js';

/**
 * Markdown renderer with syntax highlighting for fenced code blocks.
 * Known languages get hljs token markup; unknown/absent languages are escaped.
 */
export const md: MarkdownIt = new MarkdownIt({
  html: true,
  linkify: true,
  typographer: true,
  highlight(code: string, lang: string): string {
    if (lang && hljs.getLanguage(lang)) {
      const { value } = hljs.highlight(code, { language: lang, ignoreIllegals: true });
      return `<pre class="hljs"><code class="language-${lang}">${value}</code></pre>`;
    }
    return `<pre class="hljs"><code>${md.utils.escapeHtml(code)}</code></pre>`;
  },
});

export function renderMarkdown(source: string): string {
  return md.render(source);
}

import Handlebars from 'handlebars';
import fs from 'node:fs';
import path from 'node:path';

export interface TemplateEngine {
  /** Render a named page template (e.g. "post", "index", "tag") wrapped in its layout. */
  render(templateName: string, context: Record<string, unknown>, layoutName?: string): string;
  hasTemplate(name: string): boolean;
}

/**
 * Template directory conventions:
 *   templates/*.hbs            page templates (post.hbs, index.hbs, tag.hbs, ...)
 *   templates/layouts/*.hbs    layouts; page output is exposed as {{{body}}}
 *   templates/partials/*.hbs   partials registered by filename ({{> header}})
 *
 * Layout resolution: explicit layoutName arg > context.layout > "default" > none.
 */
export function createTemplateEngine(templatesDir: string): TemplateEngine {
  const hbs = Handlebars.create();
  const templates = new Map<string, Handlebars.TemplateDelegate>();
  const layouts = new Map<string, Handlebars.TemplateDelegate>();

  registerHelpers(hbs);

  const readHbs = (dir: string): Array<[string, string]> => {
    if (!fs.existsSync(dir)) return [];
    return fs
      .readdirSync(dir)
      .filter((f) => f.endsWith('.hbs') || f.endsWith('.handlebars'))
      .map((f) => [f.replace(/\.(hbs|handlebars)$/, ''), fs.readFileSync(path.join(dir, f), 'utf8')]);
  };

  for (const [name, src] of readHbs(templatesDir)) templates.set(name, hbs.compile(src));
  for (const [name, src] of readHbs(path.join(templatesDir, 'layouts'))) layouts.set(name, hbs.compile(src));
  for (const [name, src] of readHbs(path.join(templatesDir, 'partials'))) hbs.registerPartial(name, src);

  return {
    hasTemplate: (name) => templates.has(name),
    render(templateName, context, layoutName) {
      const template = templates.get(templateName);
      if (!template) {
        throw new Error(`Template not found: "${templateName}" in ${templatesDir}`);
      }
      const body = template(context);
      const layoutKey =
        layoutName ?? (typeof context.layout === 'string' ? context.layout : undefined) ?? 'default';
      const layout = layouts.get(layoutKey);
      if (layoutName && !layouts.get(layoutName)) {
        throw new Error(`Layout not found: "${layoutName}" in ${path.join(templatesDir, 'layouts')}`);
      }
      if (!layout) return body;
      return layout({ ...context, body });
    },
  };
}

function registerHelpers(hbs: typeof Handlebars): void {
  hbs.registerHelper('formatDate', (date: unknown, format?: unknown) => {
    if (!(date instanceof Date) || isNaN(date.getTime())) return '';
    if (format === 'iso') return date.toISOString();
    return date.toISOString().slice(0, 10); // YYYY-MM-DD
  });
  hbs.registerHelper('eq', (a: unknown, b: unknown) => a === b);
  hbs.registerHelper('json', (v: unknown) => JSON.stringify(v));
}

import type { Page, SiteConfig } from './types.js';

function escapeXml(s: string): string {
  return s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

function absoluteUrl(baseUrl: string, url: string): string {
  return baseUrl.replace(/\/$/, '') + url;
}

/**
 * Generate an RSS 2.0 feed. Pages are sorted newest-first by date;
 * undated pages sort last. Draft pages must be filtered before calling.
 */
export function generateRss(pages: Page[], config: SiteConfig, limit = 20): string {
  const sorted = [...pages].sort(
    (a, b) => (b.frontmatter.date?.getTime() ?? 0) - (a.frontmatter.date?.getTime() ?? 0),
  );

  const items = sorted
    .slice(0, limit)
    .map((page) => {
      const link = absoluteUrl(config.baseUrl, page.url);
      const pubDate = page.frontmatter.date ? `\n      <pubDate>${page.frontmatter.date.toUTCString()}</pubDate>` : '';
      const categories = page.frontmatter.tags
        .map((t) => `\n      <category>${escapeXml(t)}</category>`)
        .join('');
      return `    <item>
      <title>${escapeXml(page.frontmatter.title)}</title>
      <link>${escapeXml(link)}</link>
      <guid>${escapeXml(link)}</guid>
      <description>${escapeXml(page.excerpt)}</description>${pubDate}${categories}
    </item>`;
    })
    .join('\n');

  return `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">
  <channel>
    <title>${escapeXml(config.title)}</title>
    <link>${escapeXml(config.baseUrl)}</link>
    <description>${escapeXml(config.description)}</description>
    <atom:link href="${escapeXml(absoluteUrl(config.baseUrl, '/feed.xml'))}" rel="self" type="application/rss+xml"/>
    <lastBuildDate>${new Date().toUTCString()}</lastBuildDate>
${items}
  </channel>
</rss>
`;
}

import fs from 'node:fs';
import path from 'node:path';
import { parseFrontmatter, makeExcerpt } from './frontmatter.js';
import { renderMarkdown } from './markdown.js';
import { createTemplateEngine } from './templates.js';
import { generateRss } from './rss.js';
import type { BuildResult, Page, SiteConfig } from './types.js';

function walkMarkdownFiles(dir: string, base = dir): string[] {
  if (!fs.existsSync(dir)) return [];
  const out: string[] = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) out.push(...walkMarkdownFiles(full, base));
    else if (/\.(md|markdown)$/i.test(entry.name)) out.push(path.relative(base, full));
  }
  return out.sort();
}

export function slugifyTag(tag: string): string {
  return tag
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

/** Load and render one markdown source file into a Page. */
export function loadPage(sourceDir: string, relPath: string): Page {
  const raw = fs.readFileSync(path.join(sourceDir, relPath), 'utf8');
  const fallbackTitle = path.basename(relPath).replace(/\.(md|markdown)$/i, '');
  const { frontmatter, body } = parseFrontmatter(raw, fallbackTitle);
  const outputPath = relPath.replace(/\.(md|markdown)$/i, '.html');
  return {
    sourcePath: relPath,
    outputPath,
    url: '/' + outputPath.split(path.sep).join('/'),
    frontmatter,
    body,
    html: renderMarkdown(body),
    excerpt: makeExcerpt(body),
  };
}

export function collectPages(config: SiteConfig): Page[] {
  const pages = walkMarkdownFiles(config.source).map((rel) => loadPage(config.source, rel));
  return config.drafts ? pages : pages.filter((p) => !p.frontmatter.draft);
}

export function groupByTag(pages: Page[]): Map<string, Page[]> {
  const groups = new Map<string, Page[]>();
  for (const page of pages) {
    for (const tag of page.frontmatter.tags) {
      const list = groups.get(tag) ?? [];
      list.push(page);
      groups.set(tag, list);
    }
  }
  return groups;
}

function byDateDesc(a: Page, b: Page): number {
  return (b.frontmatter.date?.getTime() ?? 0) - (a.frontmatter.date?.getTime() ?? 0);
}

function writeFileEnsured(filePath: string, content: string): void {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, content);
}

export interface BuildOptions {
  /** Inject a live-reload script into every HTML page (used by dev server). */
  injectReloadScript?: string;
}

/**
 * Full site build:
 *  - each markdown file -> HTML via its template (frontmatter.layout template name, default "post")
 *  - /index.html listing all pages (template "index" if present)
 *  - /tags/<slug>.html per tag (template "tag" if present)
 *  - /feed.xml RSS feed
 */
export function buildSite(config: SiteConfig, options: BuildOptions = {}): BuildResult {
  if (!fs.existsSync(config.source)) {
    throw new Error(`Source directory not found: ${config.source}`);
  }
  const engine = createTemplateEngine(config.templates);
  const pages = collectPages(config);
  const sortedPages = [...pages].sort(byDateDesc);
  const tagGroups = groupByTag(pages);
  const allTags = [...tagGroups.keys()].sort().map((tag) => ({
    tag,
    slug: slugifyTag(tag),
    url: `/tags/${slugifyTag(tag)}.html`,
    count: tagGroups.get(tag)!.length,
  }));
  const wroteFiles: string[] = [];
  const site = { title: config.title, description: config.description, baseUrl: config.baseUrl, tags: allTags };

  const finalize = (html: string): string =>
    options.injectReloadScript ? injectBeforeBodyEnd(html, options.injectReloadScript) : html;

  // Content pages
  for (const page of pages) {
    const templateName =
      typeof page.frontmatter.template === 'string' && engine.hasTemplate(page.frontmatter.template)
        ? (page.frontmatter.template as string)
        : 'post';
    const html = engine.render(templateName, {
      ...page.frontmatter,
      content: page.html,
      url: page.url,
      excerpt: page.excerpt,
      site,
    });
    const dest = path.join(config.out, page.outputPath);
    writeFileEnsured(dest, finalize(html));
    wroteFiles.push(dest);
  }

  // Index page
  if (engine.hasTemplate('index')) {
    const html = engine.render('index', {
      title: config.title,
      pages: sortedPages.map(pageContext),
      site,
    });
    const dest = path.join(config.out, 'index.html');
    writeFileEnsured(dest, finalize(html));
    wroteFiles.push(dest);
  }

  // Tag index pages
  const tagPages: string[] = [];
  for (const { tag, slug } of allTags) {
    const tagged = [...tagGroups.get(tag)!].sort(byDateDesc);
    const html = engine.hasTemplate('tag')
      ? engine.render('tag', { title: `Tag: ${tag}`, tag, pages: tagged.map(pageContext), site })
      : fallbackTagHtml(tag, tagged);
    const dest = path.join(config.out, 'tags', `${slug}.html`);
    writeFileEnsured(dest, finalize(html));
    wroteFiles.push(dest);
    tagPages.push(dest);
  }

  // RSS feed
  const feedDest = path.join(config.out, 'feed.xml');
  writeFileEnsured(feedDest, generateRss(sortedPages, config));
  wroteFiles.push(feedDest);

  return { pages: sortedPages, tagPages, wroteFiles };
}

function pageContext(page: Page) {
  return {
    ...page.frontmatter,
    url: page.url,
    excerpt: page.excerpt,
  };
}

function fallbackTagHtml(tag: string, pages: Page[]): string {
  const items = pages
    .map((p) => `<li><a href="${p.url}">${p.frontmatter.title}</a></li>`)
    .join('\n');
  return `<!DOCTYPE html><html><head><meta charset="utf-8"><title>Tag: ${tag}</title></head><body><h1>Tag: ${tag}</h1><ul>\n${items}\n</ul></body></html>`;
}

export function injectBeforeBodyEnd(html: string, snippet: string): string {
  if (html.includes('</body>')) return html.replace('</body>', `${snippet}\n</body>`);
  return html + snippet;
}

import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import chokidar from 'chokidar';
import { WebSocketServer, WebSocket } from 'ws';
import { buildSite } from './build.js';
import type { SiteConfig } from './types.js';

const MIME: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.xml': 'application/xml; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.svg': 'image/svg+xml',
  '.ico': 'image/x-icon',
  '.txt': 'text/plain; charset=utf-8',
};

export function reloadScript(port: number): string {
  return `<script>
(function () {
  var ws = new WebSocket('ws://' + location.hostname + ':${port}');
  ws.onmessage = function (ev) { if (ev.data === 'reload') location.reload(); };
  ws.onclose = function () { setTimeout(function () { location.reload(); }, 1000); };
})();
</script>`;
}

export interface DevServer {
  port: number;
  close(): Promise<void>;
}

/**
 * Dev server: builds the site (with live-reload script injected), serves the
 * output directory, watches source + template dirs with chokidar, rebuilds on
 * change, and broadcasts "reload" to connected WebSocket clients.
 */
export async function startDevServer(config: SiteConfig, port = 3000): Promise<DevServer> {
  const build = () => buildSite(config, { injectReloadScript: reloadScript(port) });
  build();

  const server = http.createServer((req, res) => {
    const urlPath = decodeURIComponent((req.url ?? '/').split('?')[0]);
    let filePath = path.join(config.out, urlPath);
    // Prevent path traversal
    if (!path.resolve(filePath).startsWith(path.resolve(config.out))) {
      res.writeHead(403).end('Forbidden');
      return;
    }
    if (fs.existsSync(filePath) && fs.statSync(filePath).isDirectory()) {
      filePath = path.join(filePath, 'index.html');
    }
    if (!fs.existsSync(filePath)) {
      res.writeHead(404, { 'Content-Type': 'text/html; charset=utf-8' });
      res.end(`<h1>404 Not Found</h1><p>${urlPath}</p>${reloadScript(port)}`);
      return;
    }
    res.writeHead(200, { 'Content-Type': MIME[path.extname(filePath)] ?? 'application/octet-stream' });
    res.end(fs.readFileSync(filePath));
  });

  const wss = new WebSocketServer({ server });
  const broadcast = (msg: string) => {
    for (const client of wss.clients) {
      if (client.readyState === WebSocket.OPEN) client.send(msg);
    }
  };

  const watcher = chokidar.watch([config.source, config.templates], {
    ignoreInitial: true,
    awaitWriteFinish: { stabilityThreshold: 50, pollInterval: 10 },
  });
  let rebuildTimer: NodeJS.Timeout | undefined;
  watcher.on('all', (event, file) => {
    clearTimeout(rebuildTimer);
    rebuildTimer = setTimeout(() => {
      try {
        build();
        console.log(`[ssg] rebuilt (${event}: ${file})`);
        broadcast('reload');
      } catch (err) {
        console.error(`[ssg] rebuild failed: ${(err as Error).message}`);
      }
    }, 50);
  });

  await new Promise<void>((resolve) => server.listen(port, resolve));
  const actualPort = (server.address() as { port: number }).port;
  console.log(`[ssg] dev server running at http://localhost:${actualPort}`);

  return {
    port: actualPort,
    async close() {
      clearTimeout(rebuildTimer);
      await watcher.close();
      await new Promise<void>((resolve, reject) =>
        wss.close((e) => (e ? reject(e) : resolve())),
      );
      await new Promise<void>((resolve, reject) =>
        server.close((e) => (e ? reject(e) : resolve())),
      );
    },
  };
}

#!/usr/bin/env node
import { Command } from 'commander';
import { buildSite } from './build.js';
import { startDevServer } from './server.js';
import { DEFAULT_CONFIG, type SiteConfig } from './types.js';

interface CommonOpts {
  source: string;
  templates: string;
  out: string;
  baseUrl: string;
  title: string;
  description: string;
  drafts: boolean;
}

function toConfig(opts: CommonOpts): SiteConfig {
  return { ...DEFAULT_CONFIG, ...opts };
}

function addCommonOptions(cmd: Command): Command {
  return cmd
    .option('-s, --source <dir>', 'source directory of markdown files', DEFAULT_CONFIG.source)
    .option('-t, --templates <dir>', 'directory of Handlebars templates', DEFAULT_CONFIG.templates)
    .option('-o, --out <dir>', 'output directory', DEFAULT_CONFIG.out)
    .option('--base-url <url>', 'base URL for absolute links in the RSS feed', DEFAULT_CONFIG.baseUrl)
    .option('--title <title>', 'site title', DEFAULT_CONFIG.title)
    .option('--description <text>', 'site description', DEFAULT_CONFIG.description)
    .option('--drafts', 'include draft pages', false);
}

export function createProgram(): Command {
  const program = new Command()
    .name('ssg')
    .description('Static site generator: Markdown + YAML frontmatter -> Handlebars -> HTML')
    .version('1.0.0');

  addCommonOptions(
    program
      .command('build')
      .description('build the site once'),
  ).action((opts: CommonOpts) => {
    const config = toConfig(opts);
    const result = buildSite(config);
    console.log(`[ssg] built ${result.pages.length} page(s), ${result.tagPages.length} tag page(s) -> ${config.out}`);
  });

  addCommonOptions(
    program
      .command('serve')
      .description('build, serve, and live-reload on changes')
      .option('-p, --port <port>', 'dev server port', '3000'),
  ).action(async (opts: CommonOpts & { port: string }) => {
    await startDevServer(toConfig(opts), Number(opts.port));
  });

  return program;
}

const isDirectRun =
  process.argv[1] && import.meta.url.endsWith(process.argv[1].split('/').pop() ?? '');
if (isDirectRun) {
  createProgram()
    .parseAsync(process.argv)
    .catch((err: Error) => {
      console.error(`[ssg] error: ${err.message}`);
      process.exit(1);
    });
}

export { parseFrontmatter, makeExcerpt } from './frontmatter.js';
export { renderMarkdown, md } from './markdown.js';
export { createTemplateEngine } from './templates.js';
export { buildSite, collectPages, loadPage, groupByTag, slugifyTag, injectBeforeBodyEnd } from './build.js';
export { generateRss } from './rss.js';
export { startDevServer, reloadScript } from './server.js';
export * from './types.js';

